static unsigned checks=0;static void need(bool v,const char* why){++checks;if(!v)throw std::runtime_error(why);}
static size_t object(std::span<const uint8_t> rom,unsigned kind){for(unsigned n=0;n<1582;++n){const size_t row=0xA1C90+size_t(n)*12;if(workshop::u16(rom,row)==kind)return wt::bank(rom,workshop::u32(rom,row+4));}throw std::runtime_error("Resource missing");}
static auto palette(const std::vector<uint8_t>& rom,unsigned kind){const auto resource=object(rom,kind);return wt::block(rom,workshop::u32(rom,resource+0x30));}
static bool same(std::span<const uint8_t> a,std::span<const uint8_t> b,size_t at,size_t length){return std::equal(a.begin()+at,a.begin()+at+length,b.begin()+at);}
