 need(argc==3,"Expected internal content and a new result folder");std::ifstream file(argv[1],std::ios::binary);const std::vector<uint8_t> original((std::istreambuf_iterator<char>(file)),{});need(original.size()==0x1000000,"Internal content size invalid");const auto source=original;const auto out=fs::absolute(argv[2]);need(!fs::exists(out),"Preserve previous reports");fs::create_directories(out);
