 const auto old_egg=palette(original,0x401D),metal_egg=palette(metallic,0x401D);need(old_egg.size()==14*512&&metal_egg.size()==16*512,"Native401D palette is not extended from14 to16");need(std::equal(old_egg.begin(),old_egg.end(),metal_egg.begin()),"Gold/Silver changed the14 original egg palettes");need(metal_egg==palette(metallic,0x4002),"401D no longer shares the extended4002 palette descriptor");need(!std::equal(metal_egg.begin()+14*512,metal_egg.begin()+15*512,metal_egg.begin()+15*512),"Gold and Silver egg palettes collapsed");
 const auto source_bubble=object(original,0x4692),metal_bubble=object(metallic,0x4692);need(source_bubble==metal_bubble&&same(original,metallic,source_bubble,0x64),"Gold/Silver changed native4692 source resource");
 const auto hard=rooms::apply(metallic);need(original==source,"Composition changed source memory");need(hard.allocation_end==0xFF8410&&hard.plans.size()==24,"Actual composition changed24-course allocation budget");need(same(metallic,hard.rom,0xA1C90,1582*12),"Hard clones changed the native resource table");need(same(metallic,hard.rom,0xFC0000,0x10000),"Hard clones damaged Gold/Silver slab/selection metadata");need(object(hard.rom,0x4692)==metal_bubble&&same(metallic,hard.rom,metal_bubble,0x64),"Hard clones changed4692 definition");need(palette(hard.rom,0x401D)==metal_egg&&palette(hard.rom,0x4002)==metal_egg,"Hard clones changed401D sixteen-color palette bytes");
 std::vector<bool> permitted(original.size(),false);std::fill(permitted.begin()+rooms::allocation_start,permitted.begin()+hard.allocation_end,true);unsigned resource_pairs=0,objects=0;
 for(const auto& p:hard.plans){const auto ptr=0xA84A0+size_t(p.room)*8+4;for(unsigned i=0;i<4;++i)permitted[ptr+i]=true;need(workshop::u32(hard.rom,p.record)==0x46920000,"Appended native bubble ID changed");need(std::equal(metallic.begin()+p.source_objects,metallic.begin()+p.source_objects+size_t(p.original_count)*12,hard.rom.begin()+p.objects),"Original level object prefix changed after metals");objects+=p.original_count;unsigned bubble_count=0,egg_count=0;bool terminated=false;for(size_t i=0x60;i<0x100;i+=2){const auto id=workshop::u16(hard.rom,p.header+i);if(id==0xFFFF){terminated=true;break;}if(id==0x4692)++bubble_count;if(id==0x401D)++egg_count;}need(terminated&&bubble_count==1&&egg_count==1,"A composed course lost4692/401D preload pair");++resource_pairs;}
 bool outside_unchanged=true;for(size_t i=0;i<metallic.size();++i)if(!permitted[i]&&metallic[i]!=hard.rom[i])outside_unchanged=false;need(outside_unchanged,"Hard mutation escaped private arena/24header pointers after metals");need(std::all_of(hard.rom.begin()+hard.allocation_end,hard.rom.end(),[](uint8_t b){return b==255;}),"Composed transform overran its arena budget");
 nlohmann::json result{{"passed",true},{"checks",checks},{"courses",24},{"preload4692And401DPairs",resource_pairs},{"originalObjectPrefixesPreserved",objects},{"hardArenaFreeAfterMetals",true},{"hardAllocationStart",rooms::allocation_start},{"hardAllocationEnd",hard.allocation_end},{"native401DPaletteColors",16},{"native401DAnd4002PaletteBytesSharedAndExact",true},{"native4692ResourceUnchanged",true},{"metallicSlabUnchangedByHard",true},{"sourceMemoryUnchanged",true},{"patchedROMExported",false},{"gameLaunched",false},{"GPUUsed",false},{"floorOrOcclusionCertified",false}};std::ofstream(out/"execution.json")<<result.dump(2)<<'\n';std::cout<<result.dump()<<'\n';return 0;
